#include <cstdint>
#include <vector>

enum class State { Free, Reserve, Commit };
enum class Type { None, Private, Image, Mapped };

struct Region
{
    std::uint64_t base;
    std::uint64_t size;
    State state;
    std::uint32_t protect;
    Type type;
};

struct Totals { std::uint64_t committed{ 0 }, reserved{ 0 }, free{ 0 }; };

std::vector<Region> merge(const std::vector<Region>& regions)
{
    std::vector<Region> out;
    for (const Region& r : regions)
    {
        if (!out.empty())
        {
            Region& last{ out.back() };
            const bool touching{ last.base + last.size == r.base };
            const bool same{ last.state == r.state && last.protect == r.protect && last.type == r.type };
            if (touching && same)
            {
                last.size += r.size;
                continue;
            }
        }
        out.push_back(r);
    }
    return out;
}

Totals totals(const std::vector<Region>& regions)
{
    Totals t;
    for (const Region& r : regions)
    {
        if (r.state == State::Commit) t.committed += r.size;
        else if (r.state == State::Reserve) t.reserved += r.size;
        else t.free += r.size;
    }
    return t;
}

unitTests:
const std::uint32_t RW{ 0x04 }, R{ 0x02 };
TEST("the example")
{
    const std::vector<Region> in{
        { 0x1000, 0x1000, State::Commit, RW, Type::Private },
        { 0x2000, 0x2000, State::Commit, RW, Type::Private },
        { 0x4000, 0x1000, State::Commit, R, Type::Private },
        { 0x6000, 0x1000, State::Commit, R, Type::Private },
    };
    const auto out{ merge(in) };
    CHECK_EQ(out.size(), std::size_t{ 3 });
    CHECK_EQ(out[0].base, 0x1000ull);
    CHECK_EQ(out[0].size, 0x3000ull);
    CHECK_EQ(out[1].base, 0x4000ull);
    CHECK_EQ(out[2].base, 0x6000ull);
}
TEST("a long run merges into one")
{
    std::vector<Region> in;
    for (std::uint64_t i{ 0 }; i < 10; ++i) in.push_back({ 0x10000 + i * 0x1000, 0x1000, State::Reserve, 0, Type::Private });
    const auto out{ merge(in) };
    CHECK_EQ(out.size(), std::size_t{ 1 });
    CHECK_EQ(out[0].size, 0xA000ull);
}
TEST("different types stay apart")
{
    const auto out{ merge({ { 0x1000, 0x1000, State::Commit, R, Type::Image }, { 0x2000, 0x1000, State::Commit, R, Type::Private } }) };
    CHECK_EQ(out.size(), std::size_t{ 2 });
}
TEST("different states stay apart")
{
    const auto out{ merge({ { 0x1000, 0x1000, State::Reserve, 0, Type::Private }, { 0x2000, 0x1000, State::Commit, 0, Type::Private } }) };
    CHECK_EQ(out.size(), std::size_t{ 2 });
}
TEST("nothing to merge") { CHECK(merge({}).empty()); }
TEST("totals")
{
    const Totals t{ totals({
        { 0x0, 0x10000, State::Free, 0, Type::None },
        { 0x10000, 0x3000, State::Commit, RW, Type::Private },
        { 0x13000, 0xD000, State::Reserve, 0, Type::Private },
        { 0x20000, 0x1000, State::Commit, R, Type::Image },
    }) };
    CHECK_EQ(t.committed, 0x4000ull);
    CHECK_EQ(t.reserved, 0xD000ull);
    CHECK_EQ(t.free, 0x10000ull);
}

